(() => {
 'use strict';
 const rpc=(action,data={})=>window.ColorWinAuth.accountRpc('colorwin_admin_push',{p_action:action,p_data:data});
 const supported=()=>window.isSecureContext&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
 const decode=value=>Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-value.length%4)%4)),c=>c.charCodeAt(0));
 async function subscription(){const registration=await navigator.serviceWorker.getRegistration();return registration?.pushManager.getSubscription();}
 async function disable(){if(!supported())return;const sub=await subscription();if(!sub)return;await rpc('unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();}
 function open(){const dialog=document.createElement('dialog');dialog.className='admin-push-dialog';dialog.innerHTML='<div class="dialog-heading"><h2>Phone notifications</h2><button type="button" data-close aria-label="Close notifications">×</button></div><div class="admin-push-card"><span class="admin-push-bell" aria-hidden="true"><svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></span><small>COLOR WIN ADMIN</small><h3>Never miss a request</h3><p>Get deposit and withdrawal alerts in your phone notification tray, even when this page is closed.</p><span class="admin-push-status" role="status">Checking this device…</span></div><div class="admin-push-actions"><button type="button" class="primary" data-enable>Enable phone notifications</button><button type="button" data-test>Send test notification</button><button type="button" data-disable>Turn off on this device</button></div><p class="admin-push-help">Use Chrome on Android and tap Allow. Alert delivery follows your phone and browser notification settings.</p><p class="error" role="alert"></p>';
 document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();const status=dialog.querySelector('.admin-push-status'),error=dialog.querySelector('.error'),enable=dialog.querySelector('[data-enable]'),test=dialog.querySelector('[data-test]'),off=dialog.querySelector('[data-disable]');
 async function paint(){if(!supported()){status.textContent='Open the HTTPS admin link in Chrome to enable notifications.';enable.disabled=test.disabled=off.disabled=true;return;}const sub=await subscription();const info=sub?await rpc('status',{endpoint:sub.endpoint}):{enabled:false};if(!dialog.isConnected)return;status.textContent=info.enabled&&Notification.permission==='granted'?'Notifications enabled on this device':Notification.permission==='denied'?'Blocked — allow notifications in Chrome site settings':'Notifications are off on this device';test.disabled=!sub||!info.enabled;off.disabled=!sub;enable.disabled=Notification.permission==='denied';}
 const busy=value=>{enable.disabled=test.disabled=off.disabled=value;};
 enable.onclick=async()=>{error.textContent='';busy(true);try{const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notification permission was not granted. Allow it in Chrome site settings.');const {publicKey}=await rpc('key');const registration=await navigator.serviceWorker.register('/admin-push-sw.js',{scope:'/'});await navigator.serviceWorker.ready;let sub=await registration.pushManager.getSubscription();if(!sub)sub=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:decode(publicKey)});await rpc('subscribe',{subscription:sub.toJSON(),origin:location.origin});status.textContent='Enabled. Send a test notification to check your phone.';}catch(e){error.textContent=e.message;}finally{await paint();}};
 test.onclick=async()=>{busy(true);error.textContent='';try{const sub=await subscription();if(!sub)throw Error('Enable notifications first.');await rpc('test',{endpoint:sub.endpoint});status.textContent='Test sent. Check your phone notification tray.';}catch(e){error.textContent=e.message;}finally{busy(false);await paint();}};
 off.onclick=async()=>{busy(true);error.textContent='';try{await disable();status.textContent='Notifications turned off.';}catch(e){error.textContent=e.message;}finally{busy(false);await paint();}};paint().catch(e=>{error.textContent=e.message;});
 }
 function bind(){const button=document.querySelector('#admin-phone-notifications');if(button)button.onclick=open;}
 window.ColorWinAdminPush={bind,disable,open};
})();
